INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (1, 'Melon-Trunk', '$MTK', '🐘💸 The Elephant in the Room is Worth $MTK: Moonshot to $1 💸🐘', 'Melon-Trunk is a 2% max supply meme coin where 70% of the supply will be burnt for a random 🍉-shaped pool prize 🏊‍♂️ in partnership with a popular space-themed 🌌 NFT project. Our team will take 10% and use it to promote 🐘-trunk memes in online communities', '69000000', 'we will be buying up our own dips to create a fake pump story 📊, then partnering with a popular space-themed 🌌 NFT project to give away 70% of our supply to random 🍉-shaped NFT holders 🏆', '20%', '10%', '30%', '40%', 'random', '{"animal":{"emoji":"🐘","name":"Elephant"},"food":{"emoji":"🍉","name":"Watermelon"},"vibe":{"emoji":"🌌","name":"Milky Way"}}', null, '2025-12-05 00:54:29', '2025-12-05 00:54:29', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (2, 'InflatoPanda 🔥🐼', '$IBG', 'Eat a whole Cheeseburger 🔥🍔, get 10x your money back... or not 🤪', 'InflatoPanda is a 100% community-driven meme coin, where every day at 3am, our Inflatoon (a.k.a. ''Inflator in Chief'') will randomly select a 12-hour ''Burger Window'' where our price will inflate by a minimum of 10x, with a maximum potential of 1000x. The Inflatoon''s only goal is to make you, the degenerates, think ''I''ve got this, it''s just another 10x day''... until you don''t 🤯.', '10000000', 'We''ll be running targeted ''InflatoPanda Burger'' ads on CoinTelegraph, CCN, and other major crypto outlets, featuring a CGI Inflatoon holding a giant, blazing hot Cheeseburger 🔥🍔. Our Inflatoon will also make appearances on popular crypto Twitter influencers'' timelines, leaving a trail of $IBG ''Burger Bombs'' to fuel the InflatoPanda hype train 🚂', '20%', '15%', '30%', '35%', 'random', '{"animal":{"emoji":"🐼","name":"Panda"},"food":{"emoji":"🍔","name":"Cheeseburger"},"vibe":{"emoji":"🔥","name":"Fire"}}', null, '2025-12-06 17:33:36', '2025-12-06 17:33:36', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (3, 'Trophy Tron', '$TRONHODGE', 'Rage Quit, Win Prizes', 'This meme coin is for the rugged 47 degens who still believe. 🚀 When you roll a 🐬, see a 🥕, and feel like a 🏆 on pump.fun, it''s time to HODL TRONHODGE. Join the Trophy Tron army and rage quit your way to the top.', '120000000', 'Giveaways for every 🚀 moonshot, $1000 in prizes for every 🐋 whale, and a 🤯 50% bonus for every 1000 new holders. Follow @TrophyTron on Twitter for the latest 🚀 shenanigans', '40%', '10%', '30%', '20%', 'random', '{"animal":{"emoji":"🐬","name":"Dolphin"},"food":{"emoji":"🥕","name":"Carrot"},"vibe":{"emoji":"🏆","name":"Trophy"}}', null, '2025-12-06 17:33:52', '2025-12-06 17:33:52', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (4, 'SlurpToTheMoon', '$SLURT', 'Fuel Your Sushi FOMO', 'A memecoin born from the cosmic collision of Sloths, Sushi, and Rockets 🦥🍣🚀. SlurpToTheMoon is a community-driven token, 40% of all SLURT transactions will fuel the ''Sushi Supply Ship'' 🚀, a robot that randomly buys $JPM shares when the market crashes 💸. The other 30% goes to the devs, who will create a never-ending Sushi-themed meme factory 🍣🤪, and the remaining 30% funds a team of experts to analyze the optimal Sushi-to-Rocket ratio 🚀🔮. Don''t miss your chance to SlurpToTheMoon! 💸', '75000000', 'We''ll partner with top meme influencers to spread the word. Expect a massive airdrop, a collaboration with a popular NFT project, and a surprise Sushi-themed giveaway 🍣🎁.', '5%', '30%', '0%', '65%', 'random', '{"animal":{"emoji":"🦥","name":"Sloth"},"food":{"emoji":"🍣","name":"Sushi"},"vibe":{"emoji":"🚀","name":"Rocket"}}', null, '2025-12-06 17:38:37', '2025-12-06 17:38:37', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (5, 'TigerSaladRagers', '$TSR', 'Fuel your crypto-fueled, mid-night salad craving', 'TSR is a meme coin for those who live by the ocean, eat by the salad bar, and rage by the crypto markets. Each $TSR holder gets a 1% chance to spawn an in-game ''Tiger-Boost'' – a random 10-50x multiplier on their next trade. Don''t worry, whales will be eating salads with the best of us.', '42000000', 'Influencer partnerships with the most crypto-native salad influencers. ''TSR Salads'' – a line of crypto-themed, ocean-inspired salads will be promoted across TSR''s social media channels. Partners will receive a 1% cut of all TSR sales to fund their next meal.', '10%', '15%', '20%', '55%', 'random', '{"animal":{"emoji":"🐯","name":"Tiger"},"food":{"emoji":"🥗","name":"Salad"},"vibe":{"emoji":"🌊","name":"Wave"}}', '', '2025-12-10 01:21:58', '2025-12-10 01:21:58', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (6, 'MeltyMcLionFace', '$MLF', 'Paws-itive Trump Sentiments for Crypto Kings', 'A crypto-native meme coin inspired by the majestic Lion, melted into a delicious wheel of Cheese, under the vast expanse of the Milky Way. Each transaction will randomly allocate 50% of the fee to a ''Melty McBurn'' wallet, 20% to ''Trump''s Tasty Tipping Jar'', and 30% to a community pool for future ''Lion''s Share'' donations.', '42000000', 'Join our Telegram and Discord channels for a chance to receive a FREE Lion-themed NFT, because ''Fake News'' won''t tell you how epic our community is 🦁🧀🌌. Trust us, it''s going to be YUGE 🤯', '10%', '5%', '15%', '30%', 'random', '{"animal":{"emoji":"🦁","name":"Lion"},"food":{"emoji":"🧀","name":"Cheese"},"vibe":{"emoji":"🌌","name":"Milky Way"}}', 'Trump', '2025-12-10 01:22:31', '2025-12-10 01:22:31', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (7, 'DonutFox Coin 💸🦊🍩', '$DXC', 'Fuelled by 3am Energy Drink Hours 🕰️💥', 'We''re a degenerate''s dream, a coin that''s so lit, it''ll give you heartburn 🤯. DXC is the first and only meme coin that rewards holders with FREE donuts 🍩, because priorities 🤣. We''re not just a meme, we''re a movement 🎉.', '80000000', 'We''ll pump DXC to 1000x by partnering with popular 3am Energy Drink influencers 🤝 and hosting Donut-Eating contests 🎂. When we''re done, the entire crypto space will be laughing and aping along 💸.', '20%', '15%', '30%', '35%', 'random', '{"animal":{"emoji":"🦊","name":"Fox"},"food":{"emoji":"🍩","name":"Donut"},"vibe":{"emoji":"🕶️","name":"Sunglasses"}}', 'Coin', '2025-12-10 01:22:48', '2025-12-10 01:22:48', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (8, 'Dolphin in a Coconut Shell 💀🐬🥥', '$SHL', 'RIP to your portfolio, Elon Musk will sell you on this', 'A meme coin so fire, it''ll make you swim with the sharks. We''re launching a token that burns 2% LP fees in a pit of despair, gives 5% to Elon Musk''s space ventures, and 3% to a community pool for ''strategic'' partnerships. All while being listed on a ''major'' exchange (read: pump.fund) and having a market cap of $1 million in 6 hours.', '69000000', 'We''ll pump this to $1 million on pump.fund in 6 hours, or my name''s not ''Elon Musk'' 😈', '2%', '0%', '15%', '83%', 'random', '{"animal":{"emoji":"🐬","name":"Dolphin"},"food":{"emoji":"🥥","name":"Coconut"},"vibe":{"emoji":"💀","name":"Skull"}}', 'Elon Musk', '2025-12-10 01:22:57', '2025-12-10 01:22:57', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (9, 'Elons Nigerian Son (ENSo)', '$ENSo', 'Makes degens ape while Elon''s son shops in Abuja', 'A cryptocurrency where the protocol rewards the community with extra ENSo for every tweet that gets Elon''s son trending on Twitter. 50% of the supply will be burned quarterly to make it even more scarce. We''re not joking about this.', '100000000', 'We''ll partner with 20 influencers who claim to have Elon''s son''s DMs. They''ll promote ENSo on their 500k+ followers for a guaranteed 2x in 2 weeks. Then, we''ll go on a tour to major crypto cities, with a replica of Elon''s son''s Twitter bio as our lead sponsor. This will create FOMO that the community can''t ignore.', '40%', '20%', '10%', '30%', 'random', '{"animal":{"emoji":"🦥","name":"Sloth"},"food":{"emoji":"🍗","name":"Chicken Leg"},"vibe":{"emoji":"🎪","name":"Circus"}}', 'Elons Nigerian Son', '2025-12-10 01:23:18', '2025-12-10 01:23:18', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (10, 'Melania''s Zebra Stripes of Fortune', '$STRP', 'Chocolate coins from the planet of excess', 'Get ready for a meme coin that''s off the rails, like Melania''s taste in husbands. 🦓🍫🪐 Every time $STRP reaches a new astrological moon, 1% of the supply gets burned in a fiery inferno of crypto greatness. 20% of the burn goes to the devs to fuel their late-night 3am energy drink benders. The remaining 79% is reborn as a new community-driven fund, because we''re all in this together 🤝.', '100000000', 'We''ll pump the community with a custom-built rocket fueled by doge memes, 3am energy drink-fueled tweets, and a dash of astrologically-accurate timing 🚀👽', '2%', '20%', '5%', '73%', 'random', '{"animal":{"emoji":"🦓","name":"Zebra"},"food":{"emoji":"🍫","name":"Chocolate"},"vibe":{"emoji":"🪐","name":"Planet"}}', 'Melania', '2025-12-10 01:38:46', '2025-12-10 01:38:46', null) ON CONFLICT(id) DO NOTHING;
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, created_at, updated_at, deleted_at) VALUES (11, 'Giraffin'' for Burritos', '$GBR', 'When you know the secret to the all-night burrito', 'A meme cryptocurrency where each block is incentivized to build the world''s largest burrito, using LP tokens as wrapping paper and a 10% burn rate to fuel the snack-based supply chain. As the siren song of growth resonates, our community grows stronger, fueled by the never-ending pursuit of the perfect burrito 🚨🌯🦒', '12345678', 'We''ll be hosting ''Burrito Building Tuesdays'' where we reward our community for contributing to the burrito via tokenized wrapping paper 🎉🌯👌. Think ''Gitcoin'' for snacks. Think ''Binance'' for... well, more snacks 🤯', '10%', '8%', '12%', '70%', 'random', '{"animal":{"emoji":"🦒","name":"Giraffe"},"food":{"emoji":"🌯","name":"Burrito"},"vibe":{"emoji":"🚨","name":"Siren"}}', '', '2025-12-10 09:36:05', '2025-12-10 09:36:05', null) ON CONFLICT(id) DO NOTHING;
